-- Historical rejected read-only query; not the current publication contract.
-- Run against a migrated local D1 database. NULL bindings avoid owner data;
-- D1 rejects the compound SELECT during preparation, before reading rows.
WITH p AS (SELECT * FROM portfolio WHERE id=NULL AND user_id=NULL AND draft_rev=NULL AND status!='deleting' AND EXISTS(SELECT 1 FROM session s JOIN user u ON u.id=s.user_id WHERE s.id=NULL AND s.user_id=NULL AND s.expires_at>NULL AND u.deleting_at IS NULL)),
        c AS (SELECT j.key AS idx,j.value,json_extract(j.value,'$.type') AS type FROM p,json_each(p.draft,'$.components') j
          WHERE json_extract(j.value,'$.type') IN ('projects','skills','work-experience','text','github','contact','social-links','resume') AND coalesce(json_extract(p.draft,'$.samples.' || json_quote('components.' || json_extract(j.value,'$.id'))),0)!=1) SELECT * FROM (SELECT 'required' AS code,json_array('profile','name') AS path FROM p AS portfolio WHERE NOT coalesce(((length(trim(json_extract(draft,'$.profile.name'),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0 AND coalesce(json_extract(draft,'$.samples."profile.name"'),0)!=1)),0) UNION ALL SELECT 'required' AS code,json_array('profile','bio') AS path FROM p AS portfolio WHERE NOT coalesce(((length(trim(json_extract(draft,'$.profile.bio'),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0 AND coalesce(json_extract(draft,'$.samples."profile.bio"'),0)!=1)),0) UNION ALL SELECT 'required' AS code,json_array('profile','avatar') AS path FROM p AS portfolio WHERE NOT coalesce(((coalesce(json_extract(draft,'$.samples."profile.avatar"'),0)!=1 AND json_extract(draft,'$.profile.avatar.accepted')=1 AND EXISTS(SELECT 1 FROM asset a WHERE a.id=json_extract(draft,'$.profile.avatar.assetId') AND a.portfolio_id=portfolio.id AND a.kind='avatar' AND a.status='ready' AND a.content_type IN ('image/jpeg','image/png','image/webp')))),0) UNION ALL SELECT 'required' AS code,json_array('profile','banner') AS path FROM p AS portfolio WHERE NOT coalesce(((coalesce(json_extract(draft,'$.samples."profile.banner"'),0)!=1 AND EXISTS(SELECT 1 FROM asset a WHERE a.id=json_extract(draft,'$.profile.banner.assetId') AND a.portfolio_id=portfolio.id AND a.kind='banner' AND a.status='ready' AND a.content_type IN ('image/jpeg','image/png','image/webp')))),0) UNION ALL SELECT 'required' AS code,json_array('links') AS path FROM p AS portfolio WHERE NOT coalesce((EXISTS(SELECT 1 FROM json_each(draft,'$.links') l WHERE json_extract(l.value,'$.showInProfile')=1 AND length(trim(json_extract(l.value,'$.label'),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0 AND length(json_extract(l.value,'$.value'))>0)),0) UNION ALL SELECT 'address' AS code,json_array('requestedSubdomain') AS path FROM p WHERE NOT coalesce((EXISTS(SELECT 1 FROM subdomain_claim s WHERE s.portfolio_id=p.id AND
    ((p.subdomain IS NULL AND s.state='held' AND s.name=json_extract(p.draft,'$.requestedSubdomain')) OR
     (p.subdomain IS NOT NULL AND s.state='claimed' AND s.name=p.subdomain AND s.name=json_extract(p.draft,'$.requestedSubdomain')))
    AND NOT EXISTS(SELECT 1 FROM reserved_subdomain r WHERE r.name=s.name))),0) UNION ALL SELECT 'catalog' AS code,json_array('appearance','themeId') AS path FROM p WHERE NOT coalesce((json_extract(draft,'$.appearance.themeId') IN ('leaf','violet','clay','matcha','strawberry','coffee')),0) UNION ALL SELECT 'catalog' AS code,json_array('appearance','fontId') AS path FROM p WHERE NOT coalesce((json_extract(draft,'$.appearance.fontId') IN ('dm-sans','manrope','lora')),0) UNION ALL SELECT 'catalog' AS code,json_array('profile','decorationId') AS path FROM p WHERE NOT coalesce((json_extract(draft,'$.profile.decorationId') IS NULL OR json_extract(draft,'$.profile.decorationId') IN ('cat','hands')),0) UNION ALL SELECT 'required' AS code,json_array('profile','faceReveal','image') AS path FROM p WHERE NOT coalesce((json_extract(draft,'$.profile.faceReveal.enabled')!=1 OR json_extract(draft,'$.profile.faceReveal.image.assetId') IS NOT NULL),0) UNION ALL SELECT 'required' AS code,json_array('links',l.key,'label') AS path FROM p,json_each(draft,'$.links') l WHERE NOT coalesce((NOT (json_extract(l.value,'$.showInProfile')=1 OR (json_extract(l.value,'$.showInSocialComponent')=1 AND EXISTS(SELECT 1 FROM c WHERE type='social-links'))) OR length(trim(coalesce(json_extract(l.value,'$.label'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('links',l.key,'value') AS path FROM p,json_each(draft,'$.links') l WHERE NOT coalesce((NOT (json_extract(l.value,'$.showInProfile')=1 OR (json_extract(l.value,'$.showInSocialComponent')=1 AND EXISTS(SELECT 1 FROM c WHERE type='social-links'))) OR length(trim(coalesce(json_extract(l.value,'$.value'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','entries') AS path FROM c WHERE NOT coalesce((c.type!='projects' OR json_array_length(c.value,'$.data.entries')>0),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','entries') AS path FROM c WHERE NOT coalesce((c.type!='skills' OR json_array_length(c.value,'$.data.entries')>0),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','entries') AS path FROM c WHERE NOT coalesce((c.type!='work-experience' OR json_array_length(c.value,'$.data.entries')>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'title') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='projects' OR length(trim(coalesce(json_extract(e.value,'$.title'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'summary') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='projects' OR length(trim(coalesce(json_extract(e.value,'$.summary'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'name') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='skills' OR length(trim(coalesce(json_extract(e.value,'$.name'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','categories',e.key,'name') AS path FROM c,json_each(c.value,'$.data.categories') e WHERE NOT coalesce((c.type!='skills' OR length(trim(coalesce(json_extract(e.value,'$.name'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'role') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='work-experience' OR length(trim(coalesce(json_extract(e.value,'$.role'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'organization') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='work-experience' OR length(trim(coalesce(json_extract(e.value,'$.organization'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'startDate') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='work-experience' OR length(trim(coalesce(json_extract(e.value,'$.startDate'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'description') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='work-experience' OR length(trim(coalesce(json_extract(e.value,'$.description'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'endDate') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='work-experience' OR json_extract(e.value,'$.current')=1 OR length(trim(coalesce(json_extract(e.value,'$.endDate'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','title') AS path FROM c WHERE NOT coalesce((c.type!='text' OR length(trim(coalesce(json_extract(c.value,'$.data.title'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','body') AS path FROM c WHERE NOT coalesce((c.type!='text' OR EXISTS(SELECT 1 FROM json_tree(c.value,'$.data.body') t WHERE t.key='text' AND length(trim(coalesce(t.atom,''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0)),0) UNION ALL SELECT 'required' AS code,json_array('components',c.idx,'data','entries',e.key,'caseStudy') AS path FROM c, json_each(c.value,'$.data.entries') e WHERE NOT coalesce((c.type!='projects' OR json_type(e.value,'$.caseStudy') IS NULL OR EXISTS(SELECT 1 FROM json_tree(e.value,'$.caseStudy.body') t WHERE (t.key='text' AND length(trim(coalesce(t.atom,''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0) OR (t.key='type' AND t.atom='image'))),0) UNION ALL SELECT 'required' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','file') AS path FROM c WHERE NOT coalesce((c.type!='resume' OR json_extract(c.value,'$.data.file.assetId') IS NOT NULL),0) UNION ALL SELECT 'required' AS code,json_array('links') AS path FROM c,p WHERE NOT coalesce((c.type!='social-links' OR EXISTS(SELECT 1 FROM json_each(p.draft,'$.links') l WHERE json_extract(l.value,'$.showInSocialComponent')=1 AND length(trim(coalesce(json_extract(l.value,'$.value'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0 AND length(trim(coalesce(json_extract(l.value,'$.label'),''),char(9,10,11,12,13,32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288,65279)))>0)),0) UNION ALL SELECT 'recipient' AS code,json_insert(json_array('components',c.idx,'data'),'$[#]','recipientId') AS path FROM c,p WHERE NOT coalesce((c.type!='contact' OR EXISTS(SELECT 1 FROM contact_recipient r WHERE r.portfolio_id=p.id AND r.verified_at IS NOT NULL AND json_extract(c.value,'$.data.recipientId')=r.portfolio_id)),0)) LIMIT 51;
